"""Final matched A/B/C comparison; no model execution or additional GT reading."""
from pathlib import Path
import collections,copy,json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.run_stvg_referent_abc002 import BASE,read,put,sha
from scripts.score_stvg_referent_abc_v1 import aggregate
def main():
    d=read(BASE/'STUDY_READBACK.json');assert d['status']=='pass'and d['row_count']==160;s,p=aggregate(d['rows']);assert s==d['summary']and p==d['paired']
    for a in ('A','B','C'):assert read(BASE/'publication'/('group_'+a)/'PUBLICATION_COMPLETION.json')['status']=='complete'
    aliases={cid:f'R{i:03}'for i,cid in enumerate(sorted({r['case_id']for r in d['rows']}),1)}
    def anon(x):
        if isinstance(x,list):return[anon(y)for y in x]
        if isinstance(x,dict):return{(aliases[k]if k in aliases else k):(aliases[v]if k=='case_id'else anon(v))for k,v in x.items()if k!='decisions'}
        return x
    out=ROOT/'results/stvg_referent_abc/2026-10-16/closing001';out.mkdir(parents=True,exist_ok=False);put(out/'RESULTS.json',dict(status='complete',count=16,row_count=160,rows=anon(d['rows']),summary=s,paired=anon(p),GT_read=True,no_new_GT_scoring=True,all_signs_unknown_preserved=True));put(out/'IDENTITY_ROLE_UPDATE_CHAIN.json',dict(status='complete',semantic_rows=anon(d['semantic_rows']),usage=anon(d['usage']),selection_changes=anon(d['selection_changes']),semantic_update_chains=anon(d['semantic_update_chains']),limits='same small single-annotator panel in all arms; unknown preserved; feature/geometry success is not identity truth; no independent confirmation',GT_read=True))
    put(out/'ROOT_PUBLIC_READBACK.json',dict(status='pass',count=16,row_count=160,groups=d['groups'],source_sha256=sha(BASE/'STUDY_READBACK.json'),every_shared_control_row_exact=True,every_scalar_aggregate_and_pair_recomputed=True,B_C_common_indices_and_quotas_exact=True,GT_read=True))
    from scripts.export_stvg_lite_batch001 import public_source_text
    bindings=[]
